 "content": "def transform(grid):
    """Rotate the four satellite colors around each 2x2 block and extend diagonals."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    blocks = []
    for r in range(h - 1):
        for c in range(w - 1):
            if all(grid[rr][cc] == 2 for rr in (r, r + 1) for cc in (c, c + 1)):
                # Satellites in NW, NE, SW, SE order.
                pts = [(r - 1, c - 1), (r - 1, c + 2), (r + 2, c - 1), (r + 2, c + 2)]
                if all(0 <= y < h and 0 <= x < w and grid[y][x] != 0 and grid[y][x] != 2 for y, x in pts):
                    blocks.append(pts)
    # Each corner receives the color of the preceding corner around the block:
    # NW<-SW, NE<-NW, SW<-SE, SE<-NE.
    directions = [(-1, -1), (-1, 1), (1, -1), (1, 1)]
    for pts in blocks:
        colors = [grid[y][x] for y, x in pts]
        new_colors = [colors[2], colors[0], colors[3], colors[1]]
        for (y, x), color, (dy, dx) in zip(pts, new_colors, directions):
            yy, xx = y, x
            while 0 <= yy < h and 0 <= xx < w:
                out[yy][xx] = color
                yy += dy
                xx += dx
    return out
